(async () => {
  const root = document.querySelector('[data-window-gallery]');
  root.scrollIntoView();
  await new Promise(r => setTimeout(r, 6000));
  const canvas = root.querySelector('canvas');
  if (!canvas) return {error: 'no canvas'};
  const gl = canvas.getContext('webgl2') || canvas.getContext('webgl');
  if (!gl) return {error: 'no gl'};
  const w = canvas.width, h = canvas.height;
  const px = new Uint8Array(w * h * 4);
  gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, px);
  let max = 0, sum = 0, nonzero = 0;
  for (let i = 0; i < px.length; i += 4) {
    const v = px[i] + px[i+1] + px[i+2];
    sum += v;
    if (v > max) max = v;
    if (v > 24) nonzero++;
  }
  return {w, h, maxRgbSum: max, meanRgbSum: Math.round(sum / (px.length / 4)), litPixels: nonzero,
          glError: gl.getError(), vendor: gl.getParameter(gl.VENDOR), renderer: gl.getParameter(gl.RENDERER)};
})()
